import Foundation
import Testing
@testable import FirmwarePatcher

@Suite struct FirmwareKernelRegionTests {
    // Independent Keystone-assembled fixtures, not matcher-generated bytes.
    private func flow(_ words: [UInt32]) -> FirmwareKernelRegion.Region? {
        let data = words.reduce(into: Data()) { $0.append(ARM64.encodeU32($1)) }
        return FirmwareKernelRegion.flow(data, from: 0, to: data.count, excluding: -1,
                                         disasm: ARM64Disassembler())
    }
    private let base: UInt32 = 0xb26107e2 // mov x2, #0x180000000
    private let size: UInt32 = 0xb26107e3 // mov x3, #0x180000000

    @Test func constantsAndRegisterWidth() {
        #expect(flow([base, size]) == .init(base: 0x180000000, size: 0x180000000))
        #expect(flow([base, size, 0x52800022])?.base == 1) // mov w2, #1
        #expect(flow([base, size, 0xf2c00042])?.base == 0x280000000) // movk x2, #2, lsl #32
    }

    @Test func controlFlowAndUnknownWritesRefuse() {
        for instruction: UInt32 in [0xd65f03c0, 0xd61f0000, 0xa9400fe2, 0x91400442, 0xf8008fe2, 0x14000000] {
            // ret; br x0; ldp x2,x3,[sp]; shifted add; pre-index str.
            #expect(flow([base, size, instruction]) == nil)
        }
        #expect(flow([base, size, 0x94000001]) == nil) // bl clobbers x0...x18
    }

    @Test func spillWidthAndOverlap() {
        let spill: UInt32 = 0xf9003be2 // str x2,[sp,#0x70]
        let reload: UInt32 = 0xf9403be2 // ldr x2,[sp,#0x70]
        #expect(flow([base, size, spill, reload])?.base == 0x180000000)
        #expect(flow([base, size, spill, 0xb90077e0, reload]) == nil) // str w0,[sp,#0x74]
        #expect(flow([base, size, spill, 0xf90037e0, reload])?.base == 0x180000000) // adjacent 8-byte store
    }

    @Test func calleeSavedConstantsSurviveCalls() {
        #expect(flow([base, size, 0xaa0203f3, 0xaa0303f4, 0x94000001, 0xaa1303e2, 0xaa1403e3])
            == .init(base: 0x180000000, size: 0x180000000))
    }

    @Test func malformedMachORefusesWithoutParserTrap() {
        var data = Data(repeating: 0, count: 40)
        data.replaceSubrange(0..<4, with: ARM64.encodeU32(0xfeedfacf))
        data.replaceSubrange(4..<8, with: ARM64.encodeU32(0x0100000c))
        data.replaceSubrange(16..<20, with: ARM64.encodeU32(1))
        data.replaceSubrange(20..<24, with: ARM64.encodeU32(8))
        data.replaceSubrange(32..<36, with: ARM64.encodeU32(0x19))
        data.replaceSubrange(36..<40, with: ARM64.encodeU32(8))
        #expect(throws: (any Error).self) { try FirmwareKernelRegion.inspect(data) }
    }
}
